use crate::layout::{Layout,Rect};#[derive(Debug,Clone,PartialEq,Eq)]pub struct TabView{pub title:String,pub dirty:bool,pub rect:Rect}pub fn layout_tabs(l:Layout,tabs:&[(String,bool)])->Vec<TabView>{let mut x=12;tabs.iter().map(|(t,d)|{let w=(t.chars().count()as i32*8+56).clamp(110,260);let v=TabView{title:t.clone(),dirty:*d,rect:Rect::new(x,l.tab_bar.y+5,w,l.tab_bar.h-10)};x+=w+6;v}).collect()}
